		    SELECT NVL(MAX(menu_idx),0)+1 FROM CMS_MENU WHERE homepage_id = #{homepage_id}
		
		INSERT INTO
			CMS_MENU
		(
			homepage_id, menu_idx, parent_menu_idx, menu_url, menu_url_param,
			menu_name, menu_type, use_yn, view_yn, mobile_view_yn,
			print_seq, add_date, add_id, manage_idx, include_menu_name_yn,
			link_url, manager_idx, manager_dept, manager_name, manager_phone,
			group_idx, menu_full_path_name
			
			, menu_img
			
			
			, menu_top_icon
			
			
			, menu_left_icon
			
		)
		VALUES
		(
			#{homepage_id}, #{menu_idx} , #{parent_menu_idx}, #{menu_url}, #{menu_url_param},
			#{menu_name}, #{menu_type}, #{use_yn}, #{view_yn}, #{mobile_view_yn},
			#{print_seq}, SYSDATE, #{add_id}, #{manage_idx}, #{include_menu_name_yn},
			#{link_url}, #{manager_idx}, #{manager_dept}, #{manager_name}, #{manager_phone},
		
		
			#{menu_idx}, #{menu_name}
		
		
			#{group_idx},
			(
				SELECT
	                LTRIM(SYS_CONNECT_BY_PATH(menu_name,' > '),' >') || ' > ' || #{menu_name} AS menu_full_path_name
				FROM
					(select * from cms_menu where homepage_id = #{homepage_id})
                WHERE
                	menu_idx = #{parent_menu_idx}
                AND	homepage_id = #{homepage_id}
				CONNECT BY PRIOR menu_idx = parent_menu_idx AND homepage_id = #{homepage_id}
				START WITH parent_menu_idx = 0 AND homepage_id = #{homepage_id}
			)
		
		
		
			, #{menu_img}
		
		
			, #{menu_top_icon}
		
		
			, #{menu_left_icon}
		
		)

